import React from "react";
import styles from "./filter-pill.module.less";

export type FilterPillProps = React.PropsWithChildren<{
  onClick: React.MouseEventHandler;
  isSelected: boolean;
}>;
export const FilterPill = ({ children, onClick, isSelected }: FilterPillProps) => {
  return (
    <span className={`${isSelected ? "selected" : ""} ${styles.filterPill} body-m`} onClick={onClick} role="button">
      {children}
    </span>
  );
};
