// @ts-strict-ignore
import React from "react";
import { FilterPill, FilterPillProps } from "../filter-pill/filter-pill";
import structure from "@/core/styling/structure.module.less";
import styles from "./list-transformer-header.module.less";
import { isNonEmptyArray } from "@/core/helpers";

export type ListTransformerHeaderProps = {
  pills: (FilterPillProps & { key: string })[];
  isStickied?: boolean;
  header?: string;
  scrollRef?: React.RefObject<HTMLDivElement>;
};
export const ListTranformerHeader = ({ pills, isStickied = false, header, scrollRef }: ListTransformerHeaderProps) => {
  if (!isNonEmptyArray(pills)) {
    return null;
  }
  return (
    <>
      {header && (
        <p
          className={`heading-xs ${styles.header} ${structure.blockMaxWidthM} ${structure.blockPadded} ${structure.blockPaddedExceptOnLarge}`}
        >
          {header}
        </p>
      )}
      <div className={`${scrollRef ? styles.sticky : ""} ${isStickied ? "stickied" : ""}`} ref={scrollRef}>
        <div
          className={`${styles.pillContainer} ${structure.blockMaxWidthM} ${structure.blockPadded} ${structure.blockPaddedExceptOnLarge}`}
        >
          {pills.map(({ key, ...rest }) => {
            return <FilterPill key={key} {...rest} />;
          })}
        </div>
      </div>
    </>
  );
};
